import sys

def read_input():
    import sys
    data = sys.stdin.read().split()
    n = int(data[0])
    nodes = []
    index = 1
    parent_map = {}
    for _ in range(n):
        parent = data[index]
        key = int(data[index + 1])
        if parent == '-1':
            root_index = index // 2
        else:
            parent_map[index // 2] = int(parent) // 2
        nodes.append(key)
        index += 2
    k = int(data[index])
    search_keys = [int(x) for x in data[index + 1:index + 1 + k]]
    return nodes, parent_map, root_index, search_keys

def build_tree(nodes, parent_map, root_index):
    class TreeNode:
        def __init__(self, key):
            self.key = key
            self.left = None
            self.right = None

    node_objects = [TreeNode(key) for key in nodes]
    for child_index, parent_index in parent_map.items():
        if nodes[child_index] < nodes[parent_index]:
            node_objects[parent_index].left = node_objects[child_index]
        else:
            node_objects[parent_index].right = node_objects[child_index]
    return node_objects[root_index]

def calculate_expectation(root, search_key):
    class Result:
        def __init__(self):
            self.sum = 0
            self.count = 0

    def dfs(node, path, path_keys):
        if node is None:
            return
        path.append(node)
        path_keys.append(node.key)
        if node.left is None and node.right is None:
            for i in range(len(path)):
                mistake_node = path[i]
                if mistake_node.key > search_key:
                    if mistake_node.left is not None:
                        path[i] = mistake_node.left
                    else:
                        path[i] = mistake_node.right
                else:
                    if mistake_node.right is not None:
                        path[i] = mistake_node.right
                    else:
                        path[i] = mistake_node.left
                result.sum += path[-1].key
                result.count += 1
                path[i] = mistake_node
            path.pop()
            path_keys.pop()
            return
        dfs(node.left if search_key < node.key else node.right, path, path_keys)
        path.pop()
        path_keys.pop()

    result = Result()
    dfs(root, [], [])
    return result.sum / result.count if result.count > 0 else 0

def main():
    nodes, parent_map, root_index, search_keys = read_input()
    root = build_tree(nodes, parent_map, root_index)
    results = [calculate_expectation(root, key) for key in search_keys]
    for result in results:
        print(f"{result:.10f}")

if __name__ == "__main__":
    main()
